__NUXT_JSONP__("/rumbo-democratico/columnas", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n){return {data:[{columnas:[{slug:"derechos_digitales_en_riesgo_una_agenda_sin_financiamiento_global",title:"Derechos digitales en riesgo: una agenda sin financiamiento global",date:"2026-06-08T18:33:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002Feeabd345-0638-4e03-a62f-a3854560f13e\u002F","img-alt":"Derechos digitales",autor:g,medio:h,link:"https:\u002F\u002Festepais.com\u002Ftendencias_y_opiniones\u002Fderechos-digitales-riesgo-agenda-sin-financiamiento-global\u002F",category:a,extracto:"Javier González —miembro de Ethos Innovación en Políticas Públicas— escribe sobre la necesidad de legislar en materia de derechos digitales ante los peligros que pueden derivarse de la inteligencia artificial, cuyo uso en la vida cotidiana es cada vez mayor.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fderechos_digitales_en_riesgo_una_agenda_sin_financiamiento_global",extension:c,createdAt:i,updatedAt:i},{slug:"las_osc_pilares_de_la_gobernanza_democratica",title:"Las OSC, pilares de la gobernanza democrática",date:"2026-04-17T21:44:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002Fde706240-f2e0-4b30-ae2f-a0104389da4d\u002F-\u002Fcrop\u002F921x493\u002F17,39\u002F-\u002Fpreview\u002F",autor:e,medio:d,link:"https:\u002F\u002Fgrupoanimal.mx\u002Fopinion\u002Fosc-gobernanza-democratica-colaboracion-gobierno\u002F",category:a,extracto:"Durante décadas, las OSC han contribuido de manera sustantiva a la vida pública: generan evidencia sobre los problemas y sus causas, diseñan e implementan soluciones innovadoras, acompañan a poblaciones vulnerables y trabajan en territorios donde la presencia del Estado es limitada o inexistente.",toc:[],dir:b,path:"\u002Fcolumnas\u002Flas_osc_pilares_de_la_gobernanza_democratica",extension:c,createdAt:j,updatedAt:j},{slug:"la_corrupcion_no_es_un_fenomeno_neutral",title:"La corrupción no es un fenómeno neutral",date:"2026-01-28T16:25:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002F488f0f0c-4a9d-4ff4-94c3-d5ec28a043d2\u002F","img-alt":"Corrupción y mujeres",autor:e,medio:d,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Fcorrupcion-no-es-fenomeno-neutral",category:a,extracto:"Combatir la corrupción con perspectiva de género parte de reconocer que no todas las personas enfrentan los mismos riesgos ni cuentan con las mismas herramientas para defenderse frente a la corrupción.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fla_corrupcion_no_es_un_fenomeno_neutral",extension:c,createdAt:k,updatedAt:k},{slug:"es_posible_combatir_la_corrupcion_sin_la_participacion_ciudadana",title:"¿Es posible combatir la corrupción sin la participación ciudadana?",date:"2025-12-09T17:00:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002F16cda4ee-e0e0-4c4c-a2d2-81eecdd9bc54\u002F","img-alt":"Corrupción",autor:e,medio:"Expansión",link:"https:\u002F\u002Fpolitica.expansion.mx\u002Fvoces\u002F2025\u002F12\u002F09\u002Fes-posible-combatir-la-corrupcion-sin-la-participacion-ciudadana",category:a,extracto:"La participación ciudadana es indispensable para mover la maquinaria institucional anticorrupción a través de la denuncia, pero ¿cómo exigir que denuncie sin contar con protección suficiente?",toc:[],dir:b,path:"\u002Fcolumnas\u002Fes_posible_combatir_la_corrupcion_sin_la_participacion_ciudadana",extension:c,createdAt:f,updatedAt:f},{slug:"desconfianza_en_las_instituciones_pilar_de_la_percepcion_de_inseguridad",title:"Desconfianza en las instituciones: pilar de la percepción de inseguridad",date:"2025-12-09T16:01:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002Fb12f4ab2-217a-4c3e-a354-b36b334665ba\u002F","img-alt":"FGR",autor:"Imad Peniche",medio:d,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Fdesconfianza-en-instituciones-percepcion-inseguridad",category:a,extracto:"Los datos de la Encuesta Nacional de Victimización y Percepción sobre la Seguridad Pública muestran una clara relación entre la percepción de un mal desempeño institucional y la percepción de inseguridad. La falta de confianza en las instituciones judiciales y de seguridad alimenta un círculo vicioso en que la violencia se normaliza y la ciudadanía no encuentra propósito en acudir a las autoridades.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fdesconfianza_en_las_instituciones_pilar_de_la_percepcion_de_inseguridad",extension:c,createdAt:l,updatedAt:l},{slug:"rumbo_a_una_ley_general_de_participacion_ciudadana",title:"Rumbo a una Ley General de Participación Ciudadana",date:"2025-12-03T17:46:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002Fb2d54af3-348c-41d6-875e-5d1c6f1c3ff7\u002F",autor:"Emiliano Montes de Oca",medio:d,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Frumbo-a-una-ley-general-de-participacion-ciudadana",category:a,extracto:"Es evidente que hace falta una Ley General de Participación Ciudadana para sentar las bases mínimas en la regulación nacional, sin embargo, no cualquier ley funciona. Aquella que se apruebe debe tomar en consideración las críticas hechas por la sociedad civil, así como las buenas y malas prácticas de leyes de participación ciudadana locales, de otros ejercicios de reglamentación nacional y de otros mecanismos de vigilancia ciudadana.",toc:[],dir:b,path:"\u002Fcolumnas\u002Frumbo_a_una_ley_general_de_participacion_ciudadana",extension:c,createdAt:f,updatedAt:f},{slug:"la_democracia_que_nunca_fue",title:"La democracia que nunca fue",date:"2025-11-26T16:29:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002Fff7e2445-8ec6-4c89-b07e-01a5678dbd18\u002F","img-alt":"Democracia",autor:g,medio:h,link:"https:\u002F\u002Festepais.com\u002Ftendencias_y_opiniones\u002Fldemocracia-nunca-fue\u002F",category:a,extracto:"Aun cuando la Constitución establece inequívocamente nuestra forma de gobierno, es recurrente la pregunta sobre si México continúa siendo un país democrático, de cara a los fenómenos recientes de concentración de poder, eliminación de controles y cambio en las reglas del juego político. ",toc:[],dir:b,path:"\u002Fcolumnas\u002Fla_democracia_que_nunca_fue",extension:c,createdAt:m,updatedAt:m},{slug:"lineamientos_sobre_datos_abiertos_que_hay_de_nuevo",title:"Lineamientos sobre datos abiertos: ¿qué hay de nuevo?",date:"2025-10-16T15:49:01.047Z",img:"https:\u002F\u002Fucarecdn.com\u002Fefdbe729-0f8d-4dab-9dc5-3e359716ba15\u002F",autor:e,medio:d,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Flineamientos-sobre-datos-abiertos-que-hay-de-nuevo",category:a,extracto:"Abrir datos no es suficiente; el verdadero valor está en fomentar su uso, en aprovecharlos para impulsar el crecimiento, mejorar el bienestar de las personas y generar decisiones más informadas. Sin esta estrategia, los datos pueden quedar ahí, abiertos, pero sin ser usados para generar valor público.",toc:[],dir:b,path:"\u002Fcolumnas\u002Flineamientos_sobre_datos_abiertos_que_hay_de_nuevo",extension:c,createdAt:n,updatedAt:n}],total:[{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{}]}],fetch:{},mutations:[]}}("rumbo-democratico","\u002Fcolumnas",".md","Animal Político","Dalia Toledo","2026-01-04T19:38:07.810Z","Javier González","Este País","2026-07-19T00:56:17.182Z","2026-07-19T00:56:17.191Z","2026-07-19T00:56:17.189Z","2026-01-04T19:38:07.808Z","2025-12-04T03:12:47.878Z","2025-11-25T01:24:03.244Z")));